/****** Object:  StoredProcedure [VMaster].[Change_Password]    Script Date: 29 Jul 2026 18:22:12 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

 
 
create PROCEDURE [VMaster].[Change_Password]
(   @Login_id int,
	@User_Name varchar(50),
	@Old_Password varchar(50),
	@New_Password varchar(50),
	@Reason varchar(50),
	@STATUS_MASTER varchar(50),
	@User varchar(50),
	@Mac_address varchar(50)
)
as
begin
set nocount on

declare @system_old_password varchar(50)=''
select @system_old_password=isnull(PASSWORD,'') from VMaster.TBL_USER_INFO_HDR  where LOGIN_ID =@Login_id


if not exists( select 'wrong name' from VMaster.TBL_USER_INFO_HDR  where LOGIN_ID=@Login_id )
begin
	select 'error','User name is wrong'
end
else if @Old_Password<>@system_old_password
begin
	select 'Error','Old Password is wrong. enter Correct password'
end 
else
begin
 
INSERT INTO [VMaster].[TBL_CHANGE_PASSWORD_LOG]
           ([LOGIN_ID]
           ,[USER_NAME]
           ,[OLD_PASSWORD]
           ,[NEW_PASSWORD]
           ,[REASON]
           ,[STATUS_MASTER]
           ,[CREATED_BY]
           ,[CREATED_DATE]
           ,[CREATED_MAC_ADDRESS]
           ,[MODIFIED_BY]
           ,[MODIFIED_DATE]
           ,[MODIFIED_MAC_ADDRESS])
     VALUES
           (@LOGIN_ID 
           ,@USER_NAME 
           ,@OLD_PASSWORD 
           ,@NEW_PASSWORD
           ,@REASON 
           ,@STATUS_MASTER
           ,@User
           ,GETDATE ()
           ,@MAC_ADDRESS
           ,@User
           ,GETDATE ()
           ,@MAC_ADDRESS)

update VMaster.TBL_USER_INFO_HDR  set PASSWORD =@New_Password where LOGIN_ID =@Login_id
select '','Password Changed Successfully.. Pleast Try now'
end
end
GO
