CREATE PROCEDURE [VMaster].[DELETE_AIRLINES_MASTER]
(
@AIRLINE_ID INT,
@USER VARCHAR(50),
@ROLE VARCHAR(50),
@MAC_ADDRESS VARCHAR(50)
) 
AS 
BEGIN
SET NOCOUNT ON 

if @ROLE <>'Admin'
begin
select 'error','No Rights To Delete',''
end
else IF NOT EXISTS (SELECT 'X' FROM [VMaster].[TBL_AIRLINES_MASTER] WHERE AIRLINE_ID=@AIRLINE_ID)
BEGIN
	SELECT 'Error','RECORD NOT EXISTS SUCCESSFULL',@AIRLINE_ID 
END

ELSE BEGIN
DELETE [VMaster].[TBL_AIRLINES_MASTER] 
WHERE AIRLINE_ID=@AIRLINE_ID

SELECT '','RECORD DELETED SUCCESSFULL',@AIRLINE_ID 

END
END

