CREATE PROCEDURE [VMaster].[DELETE_AMMUNITION_BRAND_MASTER]
(
    @AMMUNITION_BRAND_ID INT,
    @USER VARCHAR(50) = NULL,
    @ROLE VARCHAR(50) = NULL,
    @MAC_ADDRESS VARCHAR(50) = NULL
)
AS
BEGIN
    SET NOCOUNT ON;

    IF @ROLE IS NOT NULL AND @ROLE <> 'Admin'
    BEGIN
        SELECT 'error', 'No Rights To Delete', '';
    END
    ELSE IF NOT EXISTS (
        SELECT 1 
        FROM [VMaster].[TBL_AMMUNITION_BRAND_Master] 
        WHERE AMMUNITION_BRAND_ID = @AMMUNITION_BRAND_ID
    )
    BEGIN
        SELECT 'error', 'Record Does Not Exist', @AMMUNITION_BRAND_ID;
    END
    ELSE
    BEGIN
        DELETE FROM [VMaster].[TBL_AMMUNITION_BRAND_Master]
        WHERE AMMUNITION_BRAND_ID = @AMMUNITION_BRAND_ID;

        SELECT '', 'Record Deleted Successfully', @AMMUNITION_BRAND_ID;
    END
END

