CREATE   PROCEDURE [VMaster].[DELETE_BUSINESS_PARTNER_MASTER]
(
    @BP_ID INT,
    @USER VARCHAR(50),
    @ROLE VARCHAR(50),
    @MAC_ADDRESS VARCHAR(50)
)
AS
BEGIN
    SET NOCOUNT ON

    IF UPPER(@ROLE) <> 'ADMIN'
    BEGIN
        SELECT 'ERROR','NO RIGHTS TO DELETE',''
 
    END

    IF NOT EXISTS
    (
        SELECT 'CKECK EXISTS'
        FROM [VMaster].[TBL_BUSINESS_PARTNER_MASTER]
        WHERE BP_ID=@BP_ID
    )
    BEGIN
        SELECT 'ERROR','RECORD DOES NOT EXIST',''
 
    END

    DELETE
    FROM [VMaster].[TBL_BUSINESS_PARTNER_MASTER]
    WHERE BP_ID=@BP_ID

    SELECT '','RECORD DELETED SUCCESSFULLY',@BP_ID
END
 

GO
