/****** Object:  StoredProcedure [VMaster].[GET_MAN_POWER_APPROVED_SETTINGS]    Script Date: 29 Jul 2026 18:22:12 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [VMaster].[GET_MAN_POWER_APPROVED_SETTINGS]
(
@MAN_POWER_APPROVED_ID INT
)
AS
BEGIN
    SET NOCOUNT ON

    SELECT
        MAN_POWER_APPROVED_ID,
        COMPANY_NAME ,
        DEPARTMENT_NAME ,
        DESIGNATION_NAME,
        EMPLOYMENT_TYPE_NAME,
        NEW_APPROVED_MAN_POWER,
        MAN_POWER_REQUEST_ID,
        APPROVED_BY,
        a.REMARKS,
        a.STATUS_MASTER
    FROM [VMaster].[TBL_MAN_POWER_APPROVED_SETTINGS] a
inner join  VMaster.TBL_COMPANY_MASTER c on a.COMPANY_ID=c.COMPANY_ID 
	inner join  VMaster.TBL_DEPARTMENT_MASTER d on a.DEPARTMENT_ID =d.DEPARTMENT_ID 
	inner join  VMaster.TBL_DESIGNATION_MASTER ds on a.DESIGNATION_ID  =ds.DESIGNATION_ID 
	inner join [VMaster].[TBL_EMPLOYMENT_TYPE_MASTER] emp on a. EMPLOYMENT_TYPE_ID=emp.EMPLOYMENT_TYPE_ID
    WHERE MAN_POWER_APPROVED_ID = @MAN_POWER_APPROVED_ID
END
 

