/****** Object:  StoredProcedure [VMaster].[Load_Main_Menu_Using_Role_Id]    Script Date: 29 Jul 2026 18:22:12 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


-- [vmaster].[Load_Main_Menu_Using_Role_Id] 3
CREATE PROCEDURE [VMaster].[Load_Main_Menu_Using_Role_Id]
(
	@Role_Id int
)
as
begin
set nocount on
	
select distinct a.main_menu_id,a.main_menu_name,main_menu_seq_id,isnull(a.style_css,'')'style_css',isnull(A.page_action,'')'page_action' 
from vmaster.tbl_main_menu as a 
inner join vmaster.tbl_sub_menu as b on a.main_menu_id=b.main_menu_id
	and a.status_master='AC'
inner join vmaster.tbl_links_and_pages as c on b.sub_menu_id=c.sub_menu_id
	and c.status_master='AC'
inner join vmaster.tbl_role_to_link_and_page as d on d.link_id_role_to_link=c.link_id
	and d.status_role_to_link='AC' 
where
	d.role_id_role_to_link=@Role_Id
	--and a.MAIN_MENU_ID=14
	order by main_menu_seq_id
	
end
GO
