/****** Object:  StoredProcedure [VMaster].[Load_Sub_Menu_Using_Rold_Main_Menu_Id]    Script Date: 29 Jul 2026 18:22:12 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE PROCEDURE [VMaster].[Load_Sub_Menu_Using_Rold_Main_Menu_Id]
(
	@Role_Id int,
	@Main_Menu_Id int
)
as
begin
set nocount on
	
select distinct b.sub_menu_id,b.sub_menu_name,b.sub_menu_seq_id,isnull(b.style_css,'')'style_css',isnull(b.page_action,'')'page_action' from vmaster.tbl_main_menu as a 
inner join vmaster.tbl_sub_menu as b on a.main_menu_id=b.main_menu_id
	and a.status_master='AC'
inner join vmaster.tbl_links_and_pages as c on b.sub_menu_id=c.sub_menu_id
	and b.status_master='AC'
inner join vmaster.tbl_role_to_link_and_page as d on d.link_id_role_to_link=c.link_id
	and c.status_master='AC' 
where
	d.role_id_role_to_link=@Role_Id
	and a.main_menu_id=@Main_Menu_Id
	order by b.sub_menu_seq_id
	
end

