/****** Object:  StoredProcedure [VMaster].[SAVE_AIRLINES_MASTER]    Script Date: 29 Jul 2026 18:22:12 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
 CREATE PROCEDURE [VMaster].[SAVE_AIRLINES_MASTER]
(
	@AIRLINE_ID INT ,
	@AIRLINE_NAME VARCHAR(10),
	@REMARKS VARCHAR(100),
	@STATUS_MASTER VARCHAR(20),
	@USER VARCHAR(50),
	@MAC_ADDRESS VARCHAR(50) 
	
) 
AS 
BEGIN 
SET NOCOUNT ON

IF EXISTS(SELECT 'X' FROM [VMaster].[TBL_AIRLINES_MASTER] r WHERE AIRLINE_NAME=@AIRLINE_NAME )
BEGIN
	SELECT 'ERROR','AIRLINE NAME ALREADY EXISTS','0'
END

ELSE BEGIN

INSERT INTO [VMaster].[TBL_AIRLINES_MASTER]
           ([AIRLINE_NAME]
           ,[REMARKS]
           ,[STATUS_MASTER]
           ,[CREATED_BY]
           ,[CREATED_DATE]
           ,[CREATED_MAC_ADDRESS]
           ,[MODIFIED_BY]
           ,[MODIFIED_DATE]
           ,[MODIFIED_MAC_ADDRESS])
     VALUES
           (@AIRLINE_NAME
           ,@REMARKS
           ,@STATUS_MASTER
           ,@USER
           ,GETDATE()
           ,@MAC_ADDRESS
           ,@USER
           ,GETDATE()
           ,@MAC_ADDRESS)

		DECLARE @lasted_inserted_id INT = SCOPE_IDENTITY();
		SELECT'' AS STATUS,'Data Saved Successfully' AS MESSAGE, @lasted_inserted_id AS DATA;

END
END

GO
/****** Object:  StoredProcedure [VMaster].[SAVE_AIRPORT_MASTER]    Script Date: 29 Jul 2026 18:22:12 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [VMaster].[SAVE_AIRPORT_MASTER]
(
	@AIRPORT_NAME VARCHAR(10),
	@COUNTRY_ID INT,
	@REGION_ID INT,
	@DISTRICT_ID INT,
	@LOCATION_NAME VARCHAR(50),
	@AIRPORT_ADDRESS VARCHAR(150),
	@REMARKS VARCHAR(100),
	@STATUS_MASTER VARCHAR(20),
	@USER VARCHAR(50),
	@MAC_ADDRESS VARCHAR(50)
)
AS
BEGIN
SET NOCOUNT ON

IF EXISTS
(
	SELECT 'X' 
	FROM [VMaster].[TBL_AIRPORT_MASTER]
	WHERE AIRPORT_NAME=@AIRPORT_NAME
	AND LOCATION_NAME=@LOCATION_NAME
)
BEGIN
	SELECT 'error','AIRPORT MASTER ALREADY EXISTS','0'
END

ELSE
BEGIN

INSERT INTO [VMaster].[TBL_AIRPORT_MASTER]
(
	[AIRPORT_NAME],
	[COUNTRY_ID],
	[REGION_ID],
	[DISTRICT_ID],
	[LOCATION_NAME],
	[AIRPORT_ADDRESS],
	[REMARKS],
	[STATUS_MASTER],
	[CREATED_BY],
	[CREATED_DATE],
	[CREATED_MAC_ADDRESS],
	[MODIFIED_BY],
	[MODIFIED_DATE],
	[MODIFIED_MAC_ADDRESS]
)
VALUES
(
	@AIRPORT_NAME,
	@COUNTRY_ID,
	@REGION_ID,
	@DISTRICT_ID,
	@LOCATION_NAME,
	@AIRPORT_ADDRESS,
	@REMARKS,
	@STATUS_MASTER,
	@USER,
	GETDATE(),
	@MAC_ADDRESS,
	@USER,
	GETDATE(),
	@MAC_ADDRESS
)

DECLARE @last_inserted_id INT = SCOPE_IDENTITY();

SELECT '' AS STATUS,'Data Saved Successfully' AS MESSAGE,@last_inserted_id AS DATA

END
END
 
GO
