CREATE PROCEDURE [VMaster].[SAVE_ANIMAL_HUNTING_CHARGES_MASTER_HDR]
(
    @ANIMAL_HUNT_CHARGE_ID INT,
    @COMPANY_ID INT,
    @EFFECTIVE_YEAR VARCHAR(10),
    @ISSUING_AUTHORITY VARCHAR(50),
    @APPROVAL_REFERENCE_NO VARCHAR(50),
    @APPROVAL_DATE DATETIME,
    @EFFECTIVE_FROM DATETIME,
    @EFFECTIVE_TO DATETIME,
    @CURRENCY_ID INT,
    @REMARKS VARCHAR(1000),
    @STATUS_MASTER VARCHAR(20),
    @USER VARCHAR(50),
    @MAC_ADDRESS VARCHAR(50)
)
AS
BEGIN
SET NOCOUNT ON

IF EXISTS(SELECT 'X' FROM [VMaster].[TBL_ANIMAL_HUNTING_CHARGES_MASTER_HDR] WHERE COMPANY_ID=@COMPANY_ID   AND EFFECTIVE_YEAR=@EFFECTIVE_YEAR)
BEGIN
    SELECT 'ERROR','RECORD ALREADY EXISTS','0'
