CREATE PROCEDURE [VMaster].[SAVE_ANIMAL_MASTER](
	@ANIMAL_ID  int ,
	@ANIMAL_NAME varchar(50) ,
	@ADDRESS varchar(50) ,
	@EXCHANGE_RATE decimal(15, 5) ,
	@REMARKS varchar(1000) ,
	@STATUS_MASTER varchar(20) ,
	@USER varchar(50) ,
	@MAC_ADDRESS varchar(50) 
	)
	as 
	begin 
	set nocount on

	if exists (select 'check exists' from [VMaster].[TBL_ANIMAL_MASTER] where ANIMAL_NAME =@ANIMAL_NAME ) 
	begin
	select 'error','Animal Name Already Exists',''
	end
	else begin
	
INSERT INTO [VMaster].[TBL_ANIMAL_MASTER]
           ([ANIMAL_NAME]
     
           ,[REMARKS]
           ,[STATUS_MASTER]
           ,[CREATED_BY]
           ,[CREATED_DATE]
           ,[CREATED_MAC_ADDRESS]
           ,[MODIFIED_BY]
           ,[MODIFIED_DATE]
           ,[MODIFIED_MAC_ADDRESS])
     VALUES
           (@ANIMAL_NAME 
        
           ,@REMARKS
           ,@STATUS_MASTER 
           ,@User
           ,GETDATE ()
           ,@MAC_ADDRESS 
           ,@User 
           ,GETDATE ()
           ,@MAC_ADDRESS)


		   			   
		DECLARE @lasted_inserted_id INT = SCOPE_IDENTITY();
		SELECT'' AS STATUS,'Data Saved Successfully' AS MESSAGE, @lasted_inserted_id AS DATA;

	end
	end
 

