CREATE   PROCEDURE [VMaster].[SAVE_BUSINESS_PARTNER_MASTER]
(
    @BP_ID INT OUTPUT,
    @BP_TYPE VARCHAR(50),
    @BP_NAME VARCHAR(250),
    @BP_SHORT_CODE VARCHAR(50),
    @TIN_NUMBER VARCHAR(100),
    @VAT_NUMBER VARCHAR(50),
    @CONTACT_PERSON VARCHAR(50),
    @CONTACT_NUMBER VARCHAR(50),
    @ADDRESS VARCHAR(1500),
    @EMAIL_ADDRESS VARCHAR(100),
    @PHONE_NUMBER_2 VARCHAR(50),
    @COUNTRY_ID INT,
    @REGION_ID INT,
    @DISTRICT_ID INT,
    @LOCATION VARCHAR(100),
    @NATURE_OF_BUSINESS VARCHAR(50),
    @CREDIT_ALLOWED VARCHAR(50),
    @COMPANY_HEAD_CONTACT_PERSON VARCHAR(250),
    @COMPANY_HEAD_PHONE_NO VARCHAR(250),
    @COMPANY_HEAD_EMAIL VARCHAR(250),
    @ACCOUNTS_CONTACT_PERSON VARCHAR(250),
    @ACCOUNTS_PHONE_NO VARCHAR(250),
    @ACCOUNTS_EMAIL VARCHAR(250),
    @CURRENCY_ID INT,
    @PAYMENT_TERMS VARCHAR(2500),
    @REMARKS VARCHAR(2000),
    @STATUS_MASTER VARCHAR(20),
    @USER VARCHAR(50),
    @MAC_ADDRESS VARCHAR(50)
)
AS
BEGIN
    SET NOCOUNT ON;

    IF EXISTS
    (
        SELECT 'check exists'
        FROM [VMaster].[TBL_BUSINESS_PARTNER_MASTER]
        WHERE BP_NAME=@BP_NAME
    )
    BEGIN
        SELECT 'ERROR','BUSINESS PARTNER ALREADY EXISTS',''
    
    END

    INSERT INTO [VMaster].[TBL_BUSINESS_PARTNER_MASTER]
    (
        BP_TYPE,
        BP_NAME,
        BP_SHORT_CODE,
        TIN_NUMBER,
        VAT_NUMBER,
        CONTACT_PERSON,
        CONTACT_NUMBER,
        ADDRESS,
        EMAIL_ADDRESS,
        PHONE_NUMBER_2,
        COUNTRY_ID,
        REGION_ID,
        DISTRICT_ID,
        LOCATION,
        NATURE_OF_BUSINESS,
        CREDIT_ALLOWED,
        COMPANY_HEAD_CONTACT_PERSON,
        COMPANY_HEAD_PHONE_NO,
        COMPANY_HEAD_EMAIL,
        ACCOUNTS_CONTACT_PERSON,
        ACCOUNTS_PHONE_NO,
        ACCOUNTS_EMAIL,
        CURRENCY_ID,
        PAYMENT_TERMS,
        REMARKS,
        STATUS_MASTER,
        CREATED_BY,
        CREATED_DATE,
        CREATED_MAC_ADDRESS,
        MODIFIED_BY,
        MODIFIED_DATE,
        MODIFIED_MAC_ADDRESS
    )
    VALUES
    (
        @BP_TYPE,
        @BP_NAME,
        @BP_SHORT_CODE,
        @TIN_NUMBER,
        @VAT_NUMBER,
        @CONTACT_PERSON,
        @CONTACT_NUMBER,
        @ADDRESS,
        @EMAIL_ADDRESS,
        @PHONE_NUMBER_2,
        @COUNTRY_ID,
        @REGION_ID,
        @DISTRICT_ID,
        @LOCATION,
        @NATURE_OF_BUSINESS,
        @CREDIT_ALLOWED,
        @COMPANY_HEAD_CONTACT_PERSON,
        @COMPANY_HEAD_PHONE_NO,
        @COMPANY_HEAD_EMAIL,
        @ACCOUNTS_CONTACT_PERSON,
        @ACCOUNTS_PHONE_NO,
        @ACCOUNTS_EMAIL,
        @CURRENCY_ID,
        @PAYMENT_TERMS,
        @REMARKS,
        @STATUS_MASTER,
        @USER,
        GETDATE(),
        @MAC_ADDRESS,
        @USER,
        GETDATE(),
        @MAC_ADDRESS
    )

    SET @BP_ID = CAST(SCOPE_IDENTITY() AS INT)

    SELECT '','DATA SAVED SUCCESSFULLY',@BP_ID
END
 

GO
