CREATE PROCEDURE [VMaster].[SAVE_COMPANY_MASTER](
	@COMPANY_ID int ,
	@COMPANY_NAME varchar(100) ,
	@COMPANY_FULL_NAME varchar(150) ,
	@TIN_NUMBER varchar(50) ,
	@VRN_NUMBER varchar(50) ,
	@ADDRESS varchar(2000) ,
	@CONTACT_PERSON varchar(50) ,
	@CONTACT_NUMBER varchar(50) ,
	@EMAIL varchar(50) ,
	@SHORT_CODE varchar(4) ,
	@FINANCE_START_MONTH varchar(50) ,
	@FINANCE_END_MONTH varchar(50) ,
	@YEAR_CODE varchar(50) ,
	@DEFAULT_CURRENCY_ID int ,
	@TIMEZONE varchar(50) ,
	@NO_OF_USER int ,
	@WEBSITE varchar(50) ,
	@COMP_BIG_LOGO varbinary(max) ,
	@COMP_SMALL_LOGO varbinary(max) ,
	@COMP_LETTER_HEAD varbinary(max) ,
	@COMP_STAMP_LOGO varbinary(max) ,
	@REMARKS varchar(2000) ,
	@STATUS_MASTER varchar(20) ,
	@USER varchar(50) ,
	@MAC_ADDRESS varchar(50) 
	
 	) as begin set nocount on
	if exists (select 'check exists' from VMaster.TBL_COMPANY_MASTER  where COMPANY_NAME  =@COMPANY_NAME ) 
	begin
	select 'error','Company Name Already Exists',''
	end
	else begin
	 
	 
INSERT INTO [VMaster].[TBL_COMPANY_MASTER]
           ([COMPANY_NAME]
           ,[COMPANY_FULL_NAME]
           ,[TIN_NUMBER]
           ,[VRN_NUMBER]
           ,[ADDRESS]
           ,[CONTACT_PERSON]
           ,[CONTACT_NUMBER]
           ,[EMAIL]
           ,[SHORT_CODE]
           ,[FINANCE_START_MONTH]
           ,[FINANCE_END_MONTH]
           ,[YEAR_CODE]
           ,[DEFAULT_CURRENCY_ID]
           ,[TIMEZONE]
           ,[NO_OF_USER]
           ,[WEBSITE]
           ,[COMP_BIG_LOGO]
           ,[COMP_SMALL_LOGO]
           ,[COMP_LETTER_HEAD]
           ,[COMP_STAMP_LOGO]
           ,[REMARKS]
           ,[STATUS_MASTER]
           ,[CREATED_BY]
           ,[CREATED_DATE]
           ,[CREATED_MAC_ADDRESS]
           ,[MODIFIED_BY]
           ,[MODIFIED_DATE]
           ,[MODIFIED_MAC_ADDRESS])
     VALUES
           (@COMPANY_NAME
           ,@COMPANY_FULL_NAME
           ,@TIN_NUMBER
           ,@VRN_NUMBER
           ,@ADDRESS
           ,@CONTACT_PERSON
           ,@CONTACT_NUMBER
           ,@EMAIL
           ,@SHORT_CODE
           ,@FINANCE_START_MONTH
           ,@FINANCE_END_MONTH
           ,@YEAR_CODE
           ,@DEFAULT_CURRENCY_ID
           ,@TIMEZONE
           ,@NO_OF_USER
           ,@WEBSITE
           ,@COMP_BIG_LOGO
           ,@COMP_SMALL_LOGO
           ,@COMP_LETTER_HEAD
           ,@COMP_STAMP_LOGO
           ,@REMARKS
           ,@STATUS_MASTER 
           ,@USER
           ,getdate()
           ,@MAC_ADDRESS
           ,@USER 
           ,GETDATE ()
           ,@MAC_ADDRESS)


		DECLARE @lasted_inserted_id INT = SCOPE_IDENTITY();
		SELECT'' AS STATUS,'Data Saved Successfully' AS MESSAGE, @lasted_inserted_id AS DATA; 

	end
	end


