    @COMPANY_ID INT,
    @BP_ID INT,
    @CREDIT_LIMIT_DAYS INT,
    @CREDIT_LIMIT_AMOUNT DECIMAL(15,2),
    @PAYMENT_MODE_ID INT,
    @EFFECTIVE_FROM DATETIME,
    @EFFECTIVE_TO DATETIME,
    @VALID_TYPE VARCHAR(50),
    @CURRENCY_ID INT,
    @EXPECTED_NEXT_PAYMENT_DATE DATETIME,
    @EXPECTED_NEXT_PAYMENT_AMOUNT DECIMAL(15,2),
    @REQUEST_FOR VARCHAR(50),
    @SINGLE_INVOICE_REQUEST_AMOUNT DECIMAL(15,2),
    @CREDIT_LIMIT_BUFFER_DAYS INT,
    @TOTAL_OUTSTANDING_AMOUNT DECIMAL(15,2),
    @OVER_DUE_OUTSTANDING_AMOUNT DECIMAL(15,2),
    @REQUESTED_BY VARCHAR(50),
