    @RESPONSE_2_STATUS VARCHAR(50),
    @RESPONSE_2_REMARKS VARCHAR(50),
    @FINAL_RESPONSE_PERSON VARCHAR(50),
    @FINAL_RESPONSE_DATE DATETIME,
    @FINAL_RESPONSE_STATUS VARCHAR(50),
    @FINAL_RESPONSE_REMARKS VARCHAR(50),
    @REMARKS VARCHAR(2000),
    @STATUS_MASTER VARCHAR(20),
    @USER VARCHAR(50),
    @MAC_ADDRESS VARCHAR(50)
)
AS
BEGIN
SET NOCOUNT ON

IF EXISTS
(
    SELECT 'CHECK'
    FROM VMaster.TBL_CUSTOMER_CREDIT_LIMIT_DETAILS
    WHERE COMPANY_ID=@COMPANY_ID
      AND BP_ID=@BP_ID
      AND EFFECTIVE_FROM=@EFFECTIVE_FROM
)
BEGIN
    SELECT 'ERROR','CUSTOMER CREDIT LIMIT ALREADY EXISTS','';
END
ELSE
BEGIN

INSERT INTO VMaster.TBL_CUSTOMER_CREDIT_LIMIT_DETAILS
(
    COMPANY_ID,
    BP_ID,
    CREDIT_LIMIT_DAYS,
    CREDIT_LIMIT_AMOUNT,
