    OVER_DUE_OUTSTANDING_AMOUNT,
    REQUESTED_BY,
    REQUESTED_DATE,
    SECTION_HEAD_RESPONSE_PERSON,
    SECTION_HEAD_RESPONSE_DATE,
    SECTION_HEAD_RESPONSE_STATUS,
    SECTION_HEAD_RESPONSE_REMARKS,
    RESPONSE_1_PERSON,
    RESPONSE_1_DATE,
    RESPONSE_1_STATUS,
    RESPONSE_1_REMARKS,
    RESPONSE_2_PERSON,
    RESPONSE_2_DATE,
    RESPONSE_2_STATUS,
    RESPONSE_2_REMARKS,
    FINAL_RESPONSE_PERSON,
    FINAL_RESPONSE_DATE,
    FINAL_RESPONSE_STATUS,
    FINAL_RESPONSE_REMARKS,
    REMARKS,
    STATUS_MASTER,
    CREATED_BY,
    CREATED_DATE,
    CREATED_MAC_ADDRESS,
    MODIFIED_BY,
    MODIFIED_DATE,
    MODIFIED_MAC_ADDRESS
)
VALUES
(
    @COMPANY_ID,
    @BP_ID,
    @CREDIT_LIMIT_DAYS,
    @CREDIT_LIMIT_AMOUNT,
    @PAYMENT_MODE_ID,
    @EFFECTIVE_FROM,
    @EFFECTIVE_TO,
    @VALID_TYPE,
    @CURRENCY_ID,
    @EXPECTED_NEXT_PAYMENT_DATE,
    @EXPECTED_NEXT_PAYMENT_AMOUNT,
    @REQUEST_FOR,
    @SINGLE_INVOICE_REQUEST_AMOUNT,
    @CREDIT_LIMIT_BUFFER_DAYS,
    @TOTAL_OUTSTANDING_AMOUNT,
    @OVER_DUE_OUTSTANDING_AMOUNT,
    @REQUESTED_BY,
    @REQUESTED_DATE,
    @SECTION_HEAD_RESPONSE_PERSON,
    @SECTION_HEAD_RESPONSE_DATE,
    @SECTION_HEAD_RESPONSE_STATUS,
    @SECTION_HEAD_RESPONSE_REMARKS,
    @RESPONSE_1_PERSON,
    @RESPONSE_1_DATE,
    @RESPONSE_1_STATUS,
    @RESPONSE_1_REMARKS,
    @RESPONSE_2_PERSON,
    @RESPONSE_2_DATE,
    @RESPONSE_2_STATUS,
    @RESPONSE_2_REMARKS,
    @FINAL_RESPONSE_PERSON,
    @FINAL_RESPONSE_DATE,
    @FINAL_RESPONSE_STATUS,
    @FINAL_RESPONSE_REMARKS,
    @REMARKS,
    @STATUS_MASTER,
    @USER,
    GETDATE(),
    @MAC_ADDRESS,
    @USER,
    GETDATE(),
    @MAC_ADDRESS
);

