)
AS
BEGIN
    SET NOCOUNT ON

    IF EXISTS
    (
        SELECT 'CHECK'
        FROM VMaster.TBL_DRIVER_MASTER_HDR
        WHERE DRIVER_EMP_ID = @DRIVER_EMP_ID
    )
    BEGIN
        SELECT 'ERROR','DRIVER EMPLOYEE ID ALREADY EXISTS',''
     
