CREATE PROCEDURE [VMaster].[SAVE_FUEL_STATION_MASTER]
(
    @FUEL_STATIONE_ID INT OUTPUT,
    @FUEL_STATIONE_NAME VARCHAR(50),
    @COUNTRY_ID INT,
    @REGION_ID INT,
    @DISTRICT_ID INT,
    @FUEL_STATION_ADDRESS VARCHAR(200),
    @REMARKS VARCHAR(1000),
    @STATUS_MASTER VARCHAR(20),
    @USER VARCHAR(50),
    @MAC_ADDRESS VARCHAR(50)
)
AS
BEGIN
    SET NOCOUNT ON 

    IF EXISTS
    (
        SELECT 'CHECK'
        FROM VMaster.TBL_FUEL_STATION_MASTER
        WHERE FUEL_STATIONE_NAME = @FUEL_STATIONE_NAME
    )
    BEGIN
        SELECT 'ERROR','FUEL STATION NAME ALREADY EXISTS','0'
    END

    ELSE
    BEGIN

        INSERT INTO VMaster.TBL_FUEL_STATION_MASTER
        (
            FUEL_STATIONE_NAME,
            COUNTRY_ID,
            REGION_ID,
            DISTRICT_ID,
            FUEL_STATION_ADDRESS,
            REMARKS,
            STATUS_MASTER,
            CREATED_BY,
            CREATED_DATE,
            CREATED_MAC_ADDRESS,
            MODIFIED_BY,
            MODIFIED_DATE,
            MODIFIED_MAC_ADDRESS
        )
        VALUES
        (
            @FUEL_STATIONE_NAME,
            @COUNTRY_ID,
            @REGION_ID,
            @DISTRICT_ID,
            @FUEL_STATION_ADDRESS,
            @REMARKS,
            @STATUS_MASTER,
            @USER,
            GETDATE(),
            @MAC_ADDRESS,
            @USER,
            GETDATE(),
            @MAC_ADDRESS
        );

        SELECT @FUEL_STATIONE_ID = SCOPE_IDENTITY();

        SELECT '', 'DATA SAVED SUCCESSFULLY', @FUEL_STATIONE_ID

    END
END
 

