CREATE PROCEDURE [VMaster].[SAVE_LINKS_AND_PAGES]
(
@LINK_ID	int	,
@SUB_MENU_ID	int	,
@LINK_NAME	varchar(100)	,
@PAGE_ACTION	varchar(100)	,
@REDIRECTION_TYPE	varchar(100)	,
@LINK_LOCATION	varchar(100)	,
@LINK_SEQ_ID	int	,
@STYLE_CSS	varchar(1000)	,
@STATUS_MASTER	varchar(20)	,
@USER	varchar(50)	 
)
AS BEGIN SET NOCOUNT ON
BEGIN try
begin transaction

-- CHECK DUPLICATE LINK NAME
IF EXISTS(SELECT 'X' FROM [VMaster].[TBL_LINKS_AND_PAGES]     WHERE LINK_NAME=@LINK_NAME)
BEGIN
    SELECT 'ERROR','LINK NAME ALREADY EXISTS',@LINK_ID 
END


ELSE BEGIN


 INSERT INTO [vmaster].[TBL_LINKS_AND_PAGES]
           ([SUB_MENU_ID]
           ,[LINK_NAME]
           ,[PAGE_ACTION]
           ,[REDIRECTION_TYPE]
           ,[LINK_LOCATION]
           ,[LINK_SEQ_ID]
           ,[STYLE_CSS]
           ,[STATUS_MASTER]
           ,[CREATED_BY]
           ,[CREATED_DATE]
           ,[MODIFIED_BY]
           ,[MODIFIED_DATE])
     VALUES
           (@SUB_MENU_ID
           ,@LINK_NAME
           ,@PAGE_ACTION
           ,@REDIRECTION_TYPE
           ,@LINK_LOCATION
           ,@LINK_SEQ_ID
           ,@STYLE_CSS 
           ,@STATUS_MASTER 
           ,@USER
           ,GETDATE()
           ,@USER
           ,GETDATE ())

		DECLARE @lasted_inserted_id INT = SCOPE_IDENTITY();
		SELECT'' AS STATUS,'Data Saved Successfully' AS MESSAGE, @lasted_inserted_id AS DATA;

end

commit transaction
end try
begin catch
declare @msg varchar(max)=''
 set @msg = 'ERROR: ' + ERROR_MESSAGE() + ' at ' 
            + coalesce(ERROR_PROCEDURE(), '')
            + coalesce (' line:' + convert(varchar(30), ERROR_LINE()), '')
 rollback tran
 RAISERROR (@msg, 0, 1) with nowait -- ensure the message gets out
end catch
END
GO
/****** Object:  StoredProcedure [VMaster].[SAVE_MAIN_MENU]    Script Date: 29 Jul 2026 18:22:12 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- MAIN MENU SPS
CREATE PROCEDURE [VMaster].[SAVE_MAIN_MENU]
(
    @MAIN_MENU_NAME VARCHAR(100),
    @MAIN_MENU_LOCATION VARCHAR(100),
    @MAIN_MENU_SEQ_ID INT,
    @STATUS_MASTER VARCHAR(20),
    @STYLE_CSS VARCHAR(1000),
    @PAGE_ACTION VARCHAR(100),
    @USER VARCHAR(50)
)
AS
BEGIN
    SET NOCOUNT ON;

    BEGIN TRY
        BEGIN TRANSACTION;

        IF EXISTS
        (
            SELECT 1
            FROM [VMaster].[TBL_MAIN_MENU]
            WHERE UPPER(MAIN_MENU_NAME)=UPPER(@MAIN_MENU_NAME)
        )
        BEGIN
            SELECT 'error','MAIN MENU NAME ALREADY EXISTS','';
        END
        ELSE
        BEGIN
            INSERT INTO [VMaster].[TBL_MAIN_MENU]
            (
                MAIN_MENU_NAME,
                MAIN_MENU_LOCATION,
                MAIN_MENU_SEQ_ID,
                STATUS_MASTER,
                STYLE_CSS,
                PAGE_ACTION,
                CREATED_BY,
                CREATED_DATE,
                MODIFIED_BY,
                MODIFIED_DATE
            )
            VALUES
            (
                @MAIN_MENU_NAME,
                @MAIN_MENU_LOCATION,
                @MAIN_MENU_SEQ_ID,
                @STATUS_MASTER,
                @STYLE_CSS,
                @PAGE_ACTION,
                @USER,
                GETDATE(),
                @USER,
                GETDATE()
            );

		DECLARE @lasted_inserted_id INT = SCOPE_IDENTITY();
		SELECT'' AS STATUS,'Data Saved Successfully' AS MESSAGE, @lasted_inserted_id AS DATA;
        END

        COMMIT TRANSACTION;
    END TRY

    BEGIN CATCH
        IF @@TRANCOUNT > 0
            ROLLBACK TRANSACTION;

        DECLARE @MSG VARCHAR(MAX);

        SET @MSG =
            'ERROR: ' + ERROR_MESSAGE() +
            ' AT ' + ISNULL(ERROR_PROCEDURE(),'') +
            ' LINE: ' + CAST(ERROR_LINE() AS VARCHAR(10));

        RAISERROR(@MSG,16,1);
    END CATCH
END

GO
