    (
        SELECT 1
        FROM [VMaster].[TBL_ROLE_MASTER]
        WHERE UPPER(ROLE_NAME) = UPPER(@ROLE_NAME)
    )
    BEGIN
        SELECT
            'error' AS STATUS,
            'Role Name Already Exists' AS MESSAGE,
            NULL AS DATA;
        RETURN;
    END;

    INSERT INTO [VMaster].[TBL_ROLE_MASTER]
    (
        ROLE_NAME,
