SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [VMaster].[SAVE_STORE_PRODUCT_MINIMUM_STOCK]
(
    @SNO INT,
    @COMPANY_ID INT,
    @CAMP_ID INT,
    @STORE_ID INT,
    @MAIN_CATEGORY_ID INT,
    @SUB_CATEGORY_ID INT,
    @PRODUCT_ID INT,
    @MINIMUM_STOCK_PCS INT,
    @PURCHASE_ALERT_QTY DECIMAL(15,2),
    @REQUESTED_BY VARCHAR(50),
    @EFFECTIVE_FROM DATETIME,
    @EFFECTIVE_TO DATETIME,
    @REMARKS VARCHAR(2000),
    @STATUS_MASTER VARCHAR(20),
    @USER VARCHAR(50),
    @MAC_ADDRESS VARCHAR(50)
)
AS
BEGIN
SET NOCOUNT ON;

IF EXISTS
(
    SELECT 'CHECK'
    FROM VMaster.TBL_STORE_PRODUCT_MINIMUM_STOCK
    WHERE STORE_ID=@STORE_ID
      AND PRODUCT_ID=@PRODUCT_ID
)
BEGIN
    SELECT 'error' AS STATUS,
           'Minimum Stock already exists for this Product and Store.' AS MESSAGE,           0 AS DATA;
END
ELSE
BEGIN
    INSERT INTO VMaster.TBL_STORE_PRODUCT_MINIMUM_STOCK
    (
        COMPANY_ID,
        CAMP_ID,
        STORE_ID,
        MAIN_CATEGORY_ID,
        SUB_CATEGORY_ID,
        PRODUCT_ID,
        MINIMUM_STOCK_PCS,
        PURCHASE_ALERT_QTY,
        REQUESTED_BY,
        EFFECTIVE_FROM,
        EFFECTIVE_TO,
        REMARKS,
        STATUS_MASTER,
        CREATED_BY,
        CREATED_DATE,
        CREATED_MAC_ADDRESS,
        MODIFIED_BY,
        MODIFIED_DATE,
        MODIFIED_MAC_ADDRESS
    )
    VALUES
    (
        @COMPANY_ID,
        @CAMP_ID,
        @STORE_ID,
        @MAIN_CATEGORY_ID,
        @SUB_CATEGORY_ID,
        @PRODUCT_ID,
        @MINIMUM_STOCK_PCS,
        @PURCHASE_ALERT_QTY,
        @REQUESTED_BY,
        @EFFECTIVE_FROM,
        @EFFECTIVE_TO,
        @REMARKS,
        @STATUS_MASTER,
        @USER,
        GETDATE(),
        @MAC_ADDRESS,
        @USER,
        GETDATE(),
        @MAC_ADDRESS
    )

    DECLARE @ID INT=SCOPE_IDENTITY();

    SELECT 'success' AS STATUS,
           'Data Saved Successfully' AS MESSAGE,
           @ID AS DATA;
END
END
 
GO
/****** Object:  StoredProcedure [VMaster].[SAVE_SUB_MENU]    Script Date: 29 Jul 2026 18:22:13 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- SUB MENU SPS
CREATE PROCEDURE [VMaster].[SAVE_SUB_MENU]
(
    @MAIN_MENU_ID INT,
    @SUB_MENU_NAME VARCHAR(100),
    @SUB_MENU_LOCATION VARCHAR(100),
    @SUB_MENU_SEQ_ID INT,
    @STYLE_CSS VARCHAR(1000),
    @PAGE_ACTION VARCHAR(100),
    @IS_PARENT VARCHAR(25),
    @STATUS_MASTER VARCHAR(20),
    @USER VARCHAR(50)
)
AS
BEGIN
    SET NOCOUNT ON;

    BEGIN TRY
        BEGIN TRANSACTION;

        IF EXISTS
        (
            SELECT 1
            FROM [VMaster].[TBL_SUB_MENU]
            WHERE UPPER(SUB_MENU_NAME) = UPPER(@SUB_MENU_NAME)
              AND MAIN_MENU_ID = @MAIN_MENU_ID
        )
        BEGIN
            SELECT 'error', 'SUB MENU NAME ALREADY EXISTS', '';
        END
        ELSE
        BEGIN
            INSERT INTO [VMaster].[TBL_SUB_MENU]
            (
                MAIN_MENU_ID,
                SUB_MENU_NAME,
                SUB_MENU_LOCATION,
                SUB_MENU_SEQ_ID,
                STYLE_CSS,
                PAGE_ACTION,
                IS_PARENT,
                STATUS_MASTER,
                CREATED_BY,
                CREATED_DATE,
                MODIFIED_BY,
                MODIFIED_DATE
            )
            VALUES
            (
                @MAIN_MENU_ID,
                @SUB_MENU_NAME,
                @SUB_MENU_LOCATION,
                @SUB_MENU_SEQ_ID,
                @STYLE_CSS,
                @PAGE_ACTION,
                @IS_PARENT,
                @STATUS_MASTER,
                @USER,
                GETDATE(),
                @USER,
                GETDATE()
            );

            SELECT '', 'DATA SAVED SUCCESSFULLY', SCOPE_IDENTITY();
        END

        COMMIT TRANSACTION;
    END TRY

    BEGIN CATCH
        IF @@TRANCOUNT > 0
            ROLLBACK TRANSACTION;

        DECLARE @MSG VARCHAR(MAX);

        SET @MSG =
            'ERROR: ' + ERROR_MESSAGE() +
            ' AT ' + ISNULL(ERROR_PROCEDURE(), '') +
            ' LINE: ' + CAST(ERROR_LINE() AS VARCHAR(10));

        RAISERROR(@MSG, 16, 1);
    END CATCH
END
GO
/****** Object:  StoredProcedure [VMaster].[SAVE_TO_LINK_AND_PAGE]    Script Date: 29 Jul 2026 18:22:13 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [VMaster].[SAVE_TO_LINK_AND_PAGE]
(
@ROLE_TO_LINK_ID_ROLE_TO_LINK	int	,
@ROLE_ID_TO_LINK	int,
@LINK_ID_ROLE_TO_LINK	int	,
@STATUS_ROLE_TO_LINK	varchar(20)	,
@USER_ROLE_TO_LINK	varchar(50),
@MAC_ADDR_ROLE_TO_LINK	varchar(50) 
)
AS BEGIN SET NOCOUNT ON
BEGIN try
begin transaction

IF EXISTS(SELECT 'X' FROM [VMaster].[TBL_ROLE_TO_LINK_AND_PAGE]	WHERE ROLE_ID_ROLE_TO_LINK = @ROLE_ID_TO_LINK	  AND LINK_ID_ROLE_TO_LINK = @LINK_ID_ROLE_TO_LINK)
BEGIN
	SELECT '','ROLE AND LINK ALREADY MAPPED','0' 
END

else begin

 INSERT INTO [vmaster].[TBL_ROLE_TO_LINK_AND_PAGE]
           ([ROLE_ID_ROLE_TO_LINK]
           ,[LINK_ID_ROLE_TO_LINK]
           ,[STATUS_ROLE_TO_LINK]
           ,[CREATED_USER_ROLE_TO_LINK]
           ,[CREATED_DATE_ROLE_TO_LINK]
           ,[CREATED_MAC_ADDR_ROLE_TO_LINK]
           ,[MODIFIED_USER_ROLE_TO_LINK]
           ,[MODIFIED_DATE_ROLE_TO_LINK]
           ,[MODIFIED_MAC_ADDR_ROLE_TO_LINK])
     VALUES
           (@ROLE_ID_TO_LINK 
           ,@LINK_ID_ROLE_TO_LINK 
           ,@STATUS_ROLE_TO_LINK 
           ,@USER_ROLE_TO_LINK
           ,GETDATE ()
           ,@MAC_ADDR_ROLE_TO_LINK 
           ,@USER_ROLE_TO_LINK 
           ,GETDATE ()
           ,@MAC_ADDR_ROLE_TO_LINK)

SELECT '', 'DATA SAVED SUCCESSFULL', SCOPE_IDENTITY()

 end

commit transaction
end try
begin catch
declare @msg varchar(max)=''
 set @msg = 'ERROR: ' + ERROR_MESSAGE() + ' at ' 
            + coalesce(ERROR_PROCEDURE(), '')
            + coalesce (' line:' + convert(varchar(30), ERROR_LINE()), '')
 rollback tran
 RAISERROR (@msg, 0, 1) with nowait -- ensure the message gets out
end catch
      
END
GO
