CREATE PROCEDURE [VMaster].[SAVE_TRAILER_MASTER]
(
    @TRAILER_ID INT OUTPUT,
    @TRAILER_NO VARCHAR(50),
    @TRAILER_TYPE_ID INT,
    @TRAILER_CHASSIS_NO VARCHAR(100),
    @TRAILER_DESCRIPTION VARCHAR(100),
    @VEHICLE_CONTROL_NO VARCHAR(50),
    @TRAILER_OWNED_COMPANY_ID INT,
    @TITLE_HOLDER VARCHAR(50),
    @TITLE_HOLDER_TIN_NO VARCHAR(50),
    @TITLE_HOLDER_ADDRESS VARCHAR(50),
    @MAKE VARCHAR(50),
    @MODEL VARCHAR(50),
    @MODEL_NO VARCHAR(50),
    @BODY_TYPE VARCHAR(50),
    @CLASS VARCHAR(50),
    @MANUFACTURE_YEAR INT,
    @TARE_WEIGHT DECIMAL(15,2),
    @GROSS_WEIGHT DECIMAL(15,2),
    @IMPORTED_COUNTRY_ID INT,
    @IMPORTED_SUPPLIER_ID INT,
    @PURCHASE_DATE DATETIME,
    @LATEST_INSURANCE_NO VARCHAR(50),
    @INSURANCE_AMOUNT DECIMAL(15,2),
    @GOODS_CAPACITY VARCHAR(80),
    @REMARKS VARCHAR(1000),
    @STATUS_MASTER VARCHAR(20),
    @USER VARCHAR(50),
    @MAC_ADDRESS VARCHAR(50)
)
AS
BEGIN
    SET NOCOUNT ON;

    IF EXISTS
    (
        SELECT 'CHECK'
        FROM VMaster.TBL_TRAILER_MASTER_HDR
        WHERE TRAILER_NO=@TRAILER_NO
    )
    BEGIN
        SELECT 'ERROR','TRAILER NUMBER ALREADY EXISTS',''
   
    END

    INSERT INTO VMaster.TBL_TRAILER_MASTER_HDR
    (
        TRAILER_NO,
        TRAILER_TYPE_ID,
        TRAILER_CHASSIS_NO,
        TRAILER_DESCRIPTION,
        VEHICLE_CONTROL_NO,
        TRAILER_OWNED_COMPANY_ID,
        TITLE_HOLDER,
        TITLE_HOLDER_TIN_NO,
        TITLE_HOLDER_ADDRESS,
        MAKE,
        MODEL,
        MODEL_NO,
        BODY_TYPE,
        CLASS,
        MANUFACTURE_YEAR,
        TARE_WEIGHT,
        GROSS_WEIGHT,
        IMPORTED_COUNTRY_ID,
        IMPORTED_SUPPLIER_ID,
        PURCHASE_DATE,
        LATEST_INSURANCE_NO,
        INSURANCE_AMOUNT,
        GOODS_CAPACITY,
        REMARKS,
        STATUS_MASTER,
        CREATED_BY,
        CREATED_DATE,
        CREATED_MAC_ADDRESS,
        MODIFIED_BY,
        MODIFIED_DATE,
        MODIFIED_MAC_ADDRESS
    )
    VALUES
    (
        @TRAILER_NO,
        @TRAILER_TYPE_ID,
        @TRAILER_CHASSIS_NO,
        @TRAILER_DESCRIPTION,
        @VEHICLE_CONTROL_NO,
        @TRAILER_OWNED_COMPANY_ID,
        @TITLE_HOLDER,
        @TITLE_HOLDER_TIN_NO,
        @TITLE_HOLDER_ADDRESS,
        @MAKE,
        @MODEL,
        @MODEL_NO,
        @BODY_TYPE,
        @CLASS,
        @MANUFACTURE_YEAR,
        @TARE_WEIGHT,
        @GROSS_WEIGHT,
        @IMPORTED_COUNTRY_ID,
        @IMPORTED_SUPPLIER_ID,
        @PURCHASE_DATE,
        @LATEST_INSURANCE_NO,
        @INSURANCE_AMOUNT,
        @GOODS_CAPACITY,
        @REMARKS,
        @STATUS_MASTER,
        @USER,
        GETDATE(),
        @MAC_ADDRESS,
        @USER,
        GETDATE(),
        @MAC_ADDRESS
    );

    SET @TRAILER_ID=SCOPE_IDENTITY();

    SELECT '','DATA SAVED SUCCESSFULLY',@TRAILER_ID;
END
 

