        @NO_OF_AXLES,@AXLE_DISTANCE,@TITLE_HOLDER,@TITLE_HOLDER_TIN_NO,
        @TITLE_HOLDER_ADDRESS,@LATEST_INSURANCE_NO,@INSURANCE_AMOUNT,
        @MAKE,@MODEL,@MODEL_NO,@BODY_TYPE,@CLASS,@MANUFACTURE_YEAR,
        @SEATING_CAPACITY,@TARE_WEIGHT,@GROSS_WEIGHT,@FIXED_ROUTE,
        @TRUCK_STATUS,@TARGET_KM_TRUCK,@GOODS_CAPACITY,
        @REMARKS,@STATUS_MASTER,
        @USER,GETDATE(),@MAC_ADDRESS,
        @USER,GETDATE(),@MAC_ADDRESS
    )
SELECT '', 'DATA SAVED SUCCESSFULL', SCOPE_IDENTITY()
END
END
