CREATE PROCEDURE [VMaster].[SAVE_TRUCK_MASTER_FILES_UPLOAD]
(
    @SNO INT OUTPUT,
    @TRUCK_ID INT,
    @DOCUMENT_TYPE VARCHAR(50),
    @DESCRIPTIONS VARCHAR(100),
    @FILE_NAME VARCHAR(150),
    @CONTENT_TYPE VARCHAR(50),
    @CONTENT_DATA VARBINARY(MAX),
    @REMARKS VARCHAR(100),
    @STATUS_MASTER VARCHAR(20),
    @USER VARCHAR(50),
    @MAC_ADDRESS VARCHAR(50)
)
AS
BEGIN
    SET NOCOUNT ON
	IF NOT EXISTS (SELECT * FROM [VMaster].[TBL_TRUCK_MASTER_hdr]
	WHERE @TRUCK_ID=@TRUCK_ID 
	)
	BEGIN
	SELECT 'ERROR','Truck Name Not Exists',''
	END
	else begin
    INSERT INTO VMaster.TBL_TRUCK_MASTER_FILES_UPLOAD
    (
        TRUCK_ID,
        DOCUMENT_TYPE,
        DESCRIPTIONS,
        FILE_NAME,
        CONTENT_TYPE,
        CONTENT_DATA,
        REMARKS,
        STATUS_MASTER,
        CREATED_BY,
        CREATED_DATE,
        CREATED_MAC_ADDRESS,
        MODIFIED_BY,
        MODIFIED_DATE,
        MODIFIED_MAC_ADDRESS
    )
    VALUES
    (
        @TRUCK_ID,
        @DOCUMENT_TYPE,
        @DESCRIPTIONS,
        @FILE_NAME,
        @CONTENT_TYPE,
        @CONTENT_DATA,
        @REMARKS,
        @STATUS_MASTER,
        @USER,
        GETDATE(),
        @MAC_ADDRESS,
        @USER,
        GETDATE(),
        @MAC_ADDRESS
    )

SELECT '', 'DATA SAVED SUCCESSFULL', SCOPE_IDENTITY()
END
end
GO
