	@EFFECTIVE_FROM DATETIME,
	@EFFECTIVE_TO DATETIME,
	@REMARKS VARCHAR(2000),
	@STATUS_MASTER VARCHAR(20),
	@USER VARCHAR(50),
	@MAC_ADDRESS VARCHAR(50)
	
) 
AS 
BEGIN 
SET NOCOUNT ON

IF EXISTS(SELECT 'X' FROM [VMaster].[TBL_VAT_PERCENTAGE_SETTING] r 
WHERE VAT_PERCENTAGE=@VAT_PERCENTAGE 
AND EFFECTIVE_FROM=@EFFECTIVE_FROM )
BEGIN
	SELECT 'error','VAT PERCENTAGE ALREADY EXISTS','0'
END

ELSE BEGIN

INSERT INTO [VMaster].[TBL_VAT_PERCENTAGE_SETTING]
           ([VAT_PERCENTAGE]
           ,[EFFECTIVE_FROM]
           ,[EFFECTIVE_TO]
           ,[REMARKS]
           ,[STATUS_MASTER]
           ,[CREATED_BY]
           ,[CREATED_DATE]
           ,[CREATED_MAC_ADDRESS]
           ,[MODIFIED_BY]
           ,[MODIFIED_DATE]
           ,[MODIFIED_MAC_ADDRESS])
     VALUES
           (@VAT_PERCENTAGE
           ,@EFFECTIVE_FROM
           ,@EFFECTIVE_TO
           ,@REMARKS
           ,@STATUS_MASTER
           ,@USER
           ,GETDATE()
           ,@MAC_ADDRESS
           ,@USER
           ,GETDATE()
           ,@MAC_ADDRESS)

		DECLARE @lasted_inserted_id INT = SCOPE_IDENTITY();
		SELECT'' AS STATUS,'Data Saved Successfully' AS MESSAGE, @lasted_inserted_id AS DATA;

END
END

