CREATE PROCEDURE [VMaster].[SHOW_COMPANY_QUOTA_ANIMAL_MAPPING_DTL]
(
@QUOTA_ID int,
@STATUS varchar(50)
)
AS
BEGIN
SET NOCOUNT ON

SELECT
	SNO,
	QUOTA_ID,
	ANIMAL_NAME,
	OLD_APPROVED_QTY,
	ADD_REMOVE_QTY,
	NEW_APPROVED_QTY,
	a.REMARKS,
	Case when A.STATUS_MASTER ='AC' THEN 'ACTIVE' ELSE 'INACTIVE' END [STATUS_MASTER] 
FROM [VMaster].[TBL_COMPANY_QUOTA_ANIMAL_MAPPING_DTL] as  a
left join  VMaster.TBL_ANIMAL_MASTER as  b on  a.ANIMAL_ID =b.ANIMAL_ID 
where QUOTA_ID=@QUOTA_ID
AND A.STATUS_MASTER =@STATUS 

END
