/****** Object:  StoredProcedure [VMaster].[SHOW_COMPANY_QUOTA_ANIMAL_MAPPING_HDR]    Script Date: 29 Jul 2026 18:22:13 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE PROCEDURE [VMaster].[SHOW_COMPANY_QUOTA_ANIMAL_MAPPING_HDR]
(@QUOTA_ID INT,
@STATUS varchar(50)
)
AS
BEGIN
SET NOCOUNT ON

SELECT
	QUOTA_ID,
	COMPANY_NAME,
	CAMP_NAME,
	EFFECTIVE_YEAR,
	NEW_REVISION,
	OLD_QUOTA_ID,
	ISSUING_AUTHORITY,
	APPROVAL_REFERENCE_NO,
	REPLACE(CONVERT(VARCHAR(50),APPROVAL_DATE,106),' ','-') APPROVAL_DATE,
	REPLACE(CONVERT(VARCHAR(50),LAST_AMENDMENT_DATE,106),' ','-') LAST_AMENDMENT_DATE,
	REPLACE(CONVERT(VARCHAR(50),EFFECTIVE_FROM,106),' ','-') EFFECTIVE_FROM,
	REPLACE(CONVERT(VARCHAR(50),EFFECTIVE_TO,106),' ','-') EFFECTIVE_TO,	 
	QUOTA_AMOUNT,
	VAT_AMOUNT,
	FINAL_QUOTA_AMOUNT,
	CURRENCY_NAME,
	a.REMARKS,
	Case when A.STATUS_MASTER ='AC' THEN 'ACTIVE' ELSE 'INACTIVE' END [STATUS_MASTER] 
FROM VMaster.TBL_COMPANY_QUOTA_ANIMAL_MAPPING_HDR a 
left join  vmaster.TBL_COMPANY_MASTER as b on  a.COMPANY_ID =b.COMPANY_ID 
left join  VMaster.TBL_CURRENCY_MASTER as c on  c.CURRENCY_ID =a.CURRENCY_ID
left join  vmaster.TBL_CAMP_MASTER as  ca on ca.CAMP_ID =a.COMPANY_ID
where a.STATUS_MASTER =@STATUS 
and  a.QUOTA_ID=@QUOTA_ID

END


 
  
