CREATE PROCEDURE [VMaster].[SHOW_CUSTOMER_WISE_TRIP_TEMPLATE_PRICE_MAPPING]
(
@STATUS varchar(50)
)
AS
BEGIN
SET NOCOUNT ON

SELECT
      A.PRICE_CUSTOMER_ID,
      A.COMPANY_ID,
      C.COMPANY_NAME,
      A.BP_ID,
      BP.BP_NAME,
      A.TRIP_TEMPLATE_ID,
      TTM.TRIP_TEMPLATE_NAME,
      A.TRUCK_TYPE_ID,
      TTMST.TRUCK_TYPE_NAME,
      A.TRIP_AMOUNT,
      A.CURRENCY_ID,
      CUR.CURRENCY_NAME,
      A.REMARKS,
      A.STATUS_MASTER
FROM VMaster.TBL_CUSTOMER_WISE_TRIP_TEMPLATE_PRICE_MAPPING A
INNER JOIN VMaster.TBL_COMPANY_MASTER C
    ON A.COMPANY_ID = C.COMPANY_ID
INNER JOIN VMaster.TBL_BP_MASTER BP
    ON A.BP_ID = BP.BP_ID
INNER JOIN VMaster.TBL_TRIP_TEMPLATE_MASTER TTM
    ON A.TRIP_TEMPLATE_ID = TTM.TRIP_TEMPLATE_ID
INNER JOIN VMaster.TBL_TRUCK_TYPE_MASTER TTMST
    ON A.TRUCK_TYPE_ID = TTMST.TRUCK_TYPE_ID
INNER JOIN VMaster.TBL_CURRENCY_MASTER CUR
    ON A.CURRENCY_ID = CUR.CURRENCY_ID
	WHERE A.STATUS_MASTER =@STATUS 

END
 

