@STATUS varchar(50)
)
AS
BEGIN
    SET NOCOUNT ON

    SELECT
        A.SNO,
        A.DRIVER_EMP_ID,
        A.DRIVER_FULL_NAME,
        C.COMPANY_NAME,
        D.DEPARTMENT_NAME,
        DS.DESIGNATION_NAME,
        A.PHONE_NUMBER,
