/****** Object:  StoredProcedure [VMaster].[SHOW_LICENSE_PERMIT_COST_MASTER]    Script Date: 29 Jul 2026 18:22:13 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE PROCEDURE [VMaster].[SHOW_LICENSE_PERMIT_COST_MASTER]
(
 @LICENSE_PERMIT_ID varchar(50),
 @SALES_PACKAGE_TYPE_ID varchar(50),
 @PRICE_PACKAGE_ID varchar(50),
 @STATUS varchar(50)
)
AS
BEGIN

SET NOCOUNT ON

SELECT 
 a.[SNO]
,a.[LICENSE_PERMIT_ID]
,lt.LICENSE_PERMIT_NAME
,a.[SALES_PACKAGE_TYPE_ID]
,st.SALES_PACKAGE_TYPE_NAME
,a.[PRICE_TYPE_ID]
,pt.PRICE_TYPE_NAME
,a.[PRICE_PACKAGE_ID]
,p.PRICE_PACKAGE_NAME
,a.[GOVT_RATE]
,a.[ACTUAL_AMOUNT]
,a.[CURRENCY_ID]
,cu.CURRENCY_NAME
,replace(convert(varchar(50),a.EFFECTIVE_FROM,106),' ','-')  EFFECTIVE_FROM
,replace(convert(varchar(50),a.EFFECTIVE_TO,106),' ','-')  EFFECTIVE_TO
,A.[REMARKS]
,Case when A.STATUS_MASTER IN ('AC','ACTIVE') THEN 'ACTIVE' ELSE 'INACTIVE' END [STATUS_MASTER] 
FROM [VMaster].[TBL_LICENSE_PERMIT_COST_MASTER] AS A
LEFT JOIN VMASTER.TBL_LICENSE_PERMIT_TYPE_MASTER AS lt ON lt.LICENSE_PERMIT_ID = a.LICENSE_PERMIT_ID
LEFT JOIN VMASTER.TBL_SALES_PACKAGE_TYPE_MASTER AS st ON st.SALES_PACKAGE_TYPE_ID = a.SALES_PACKAGE_TYPE_ID
LEFT JOIN VMASTER.TBL_PRICE_TYPE_MASTER AS pt ON pt.PRICE_TYPE_ID = a.PRICE_TYPE_ID
LEFT JOIN VMASTER.TBL_PRICE_PACKAGE_MASTER AS p ON p.PRICE_PACKAGE_ID = a.PRICE_PACKAGE_ID
LEFT JOIN VMASTER.TBL_CURRENCY_MASTER AS cu ON cu.CURRENCY_ID = a.CURRENCY_ID
WHERE (@STATUS = '' OR @STATUS IS NULL
   OR UPPER(A.STATUS_MASTER) = @STATUS
   OR (UPPER(A.STATUS_MASTER) = 'ACTIVE' AND @STATUS = 'AC')
   OR (UPPER(A.STATUS_MASTER) = 'INACTIVE' AND @STATUS = 'IN'))
 and
	CASE when @LICENSE_PERMIT_ID  <>'' and @LICENSE_PERMIT_ID <>'0' then
	charindex(',' +convert(varchar(max),a.LICENSE_PERMIT_ID  ) +',',','+@LICENSE_PERMIT_ID +',') else 1 end >0  
and
	CASE when @SALES_PACKAGE_TYPE_ID  <>'' and @SALES_PACKAGE_TYPE_ID <>'0' then
	charindex(',' +convert(varchar(max),a.SALES_PACKAGE_TYPE_ID  ) +',',','+@SALES_PACKAGE_TYPE_ID +',') else 1 end >0  
and
	CASE when @PRICE_PACKAGE_ID  <>'' and @PRICE_PACKAGE_ID <>'0' then
	charindex(',' +convert(varchar(max),a.PRICE_PACKAGE_ID  ) +',',','+@PRICE_PACKAGE_ID +',') else 1 end >0  


END




  
GO
