CREATE PROCEDURE [VMaster].[SHOW_MAN_POWER_CHANGE_REQUEST]
(
@COMPANY_ID int,
@STATUS varchar(50)

)
AS
BEGIN    SET NOCOUNT ON

    SELECT
        MAN_POWER_REQUEST_ID,
        COMPANY_NAME ,
        DEPARTMENT_NAME ,
        DESIGNATION_NAME,
        EMPLOYMENT_TYPE_NAME,
        OLD_APPROVED_MAN_POWER,
        ADD_REMOVE_MAN_POWER,
        NEW_APPROVED_MAN_POWER,
        SECTION_HEAD_RESPONSE_STATUS,
        RESPONSE_1_STATUS,
        RESPONSE_2_STATUS,
        FINAL_RESPONSE_STATUS,
        a.REMARKS,
        CASE
            WHEN a.STATUS_MASTER = 'AC' THEN 'ACTIVE'
            ELSE 'INACTIVE'
        END AS STATUS_MASTER
    FROM [VMaster].[TBL_MAN_POWER_CHANGE_REQUEST] a
	inner join  VMaster.TBL_COMPANY_MASTER c on a.COMPANY_ID=c.COMPANY_ID 
	inner join  VMaster.TBL_DEPARTMENT_MASTER d on a.DEPARTMENT_ID =d.DEPARTMENT_ID 
	inner join  VMaster.TBL_DESIGNATION_MASTER ds on a.DESIGNATION_ID  =ds.DESIGNATION_ID 
	inner join [VMaster].[TBL_EMPLOYMENT_TYPE_MASTER] emp on a. EMPLOYMENT_TYPE_ID=emp.EMPLOYMENT_TYPE_ID
    WHERE A.STATUS_MASTER = @STATUS 
END
 

 
 
