CREATE PROCEDURE [VMaster].[SHOW_PRODUCT_MASTER]

(
@STATUS varchar(50)
)
AS
BEGIN
    SET NOCOUNT ON

    SELECT
        PRODUCT_ID,
        PRODUCT_NAME,
        MAIN_CATEGORY_ID,
        SUB_CATEGORY_ID,
        UOM_ID,
        NO_OF_PCS_PER_PACKING,
        ALTERNATE_UOM_ID,
        COST_CENTRE_ID,
        COMPANY_ID,
        PRODUCTION_COST,
        VAT_PERCENTAGE,
        REMARKS,
        STATUS_MASTER
    FROM [VMaster].[TBL_PRODUCT_MASTER]
	where STATUS_MASTER =@STATUS 
    ORDER BY PRODUCT_NAME;

END
 

