/****** Object:  StoredProcedure [VMaster].[SHOW_PRODUCT_OPENING_STOCK]    Script Date: 29 Jul 2026 18:22:13 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE PROCEDURE [VMaster].[SHOW_PRODUCT_OPENING_STOCK]
(
@STATUS varchar(50)
)
AS 
BEGIN

SET NOCOUNT ON

SELECT [SNO]
      ,REPLACE(CONVERT(VARCHAR(60),[OPENING_STOCK_DATE],106),' ','-') OPENING_STOCK_DATE
      ,[COMPANY_NAME]
      ,[CAMP_NAME]
      ,[STORE_NAME]
      ,[MAIN_CATEGORY_NAME]
      ,[SUB_CATEGORY_NAME]
      ,[PRODUCT_NAME]
      ,[QTY]
      ,[APPROVED_BY]
      ,A.[REMARKS]
,Case when A.STATUS_MASTER ='AC' THEN 'ACTIVE' ELSE 'INACTIVE' END [STATUS_MASTER] 
FROM [VMaster].[TBL_PRODUCT_OPENING_STOCK] AS  A
LEFT JOIN  VMASTER.TBL_COMPANY_MASTER AS CA ON CA.COMPANY_ID =A.COMPANY_ID
LEFT JOIN  VMASTER.TBL_CAMP_MASTER AS B ON B.CAMP_ID =A.COMPANY_ID
LEFT JOIN  VMaster.tbl_Store_Master AS S  ON  S.STORE_ID =A.STORE_ID
LEFT JOIN  VMASTER.TBL_PRODUCT_MAIN_CATEGORY_MASTER AS  MO ON MO.MAIN_CATEGORY_ID =A.MAIN_CATEGORY_ID
LEFT JOIN  VMASTER.TBL_PRODUCT_SUB_CATEGORY_MASTER AS  SU ON SU.SUB_CATEGORY_ID =A.SUB_CATEGORY_ID 
LEFT JOIN  VMASTER.TBL_PRODUCT_MASTER AS P ON P.PRODUCT_ID =A.PRODUCT_ID 

WHERE  A.STATUS_MASTER =@STATUS 


END

GO
