/****** Object:  StoredProcedure [VMaster].[SHOW_STORE_PRODUCT_MINIMUM_STOCK]    Script Date: 29 Jul 2026 18:22:13 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [VMaster].[SHOW_STORE_PRODUCT_MINIMUM_STOCK]
(
    @STATUS VARCHAR(20)
)
AS
BEGIN
SET NOCOUNT ON;

SELECT
A.SNO,
CA.COMPANY_NAME,
CM.CAMP_NAME,
ST.STORE_NAME,
MC.MAIN_CATEGORY_NAME,
SC.SUB_CATEGORY_NAME,
PM.PRODUCT_NAME,
A.MINIMUM_STOCK_PCS,
A.PURCHASE_ALERT_QTY,
A.REQUESTED_BY,
CONVERT(VARCHAR(10),A.EFFECTIVE_FROM,23) EFFECTIVE_FROM,
CONVERT(VARCHAR(10),A.EFFECTIVE_TO,23) EFFECTIVE_TO,
A.REMARKS,
CASE
    WHEN A.STATUS_MASTER='AC' THEN 'ACTIVE'
    ELSE 'INACTIVE'
END STATUS_MASTER

FROM VMaster.TBL_STORE_PRODUCT_MINIMUM_STOCK A

LEFT JOIN VMaster.TBL_COMPANY_MASTER CA
ON CA.COMPANY_ID=A.COMPANY_ID

LEFT JOIN VMaster.TBL_CAMP_MASTER CM
ON CM.CAMP_ID=A.CAMP_ID

LEFT JOIN VMaster.TBL_STORE_MASTER ST
ON ST.STORE_ID=A.STORE_ID

LEFT JOIN VMaster.TBL_PRODUCT_MAIN_CATEGORY_MASTER MC
ON MC.MAIN_CATEGORY_ID=A.MAIN_CATEGORY_ID

LEFT JOIN VMaster.TBL_PRODUCT_SUB_CATEGORY_MASTER SC
ON SC.SUB_CATEGORY_ID=A.SUB_CATEGORY_ID

LEFT JOIN VMaster.TBL_PRODUCT_MASTER PM
ON PM.PRODUCT_ID=A.PRODUCT_ID

WHERE A.STATUS_MASTER=@STATUS

END
 

GO
