CREATE PROCEDURE [VMaster].[SHOW_SUB_MENU]
(
@SUB_MENU_ID VARCHAR(50),
@STATUS varchar(50)
)
AS BEGIN SET NOCOUNT ON
 
 SELECT [SUB_MENU_ID]
      ,M.[MAIN_MENU_NAME] 
      ,[SUB_MENU_NAME]
      ,[SUB_MENU_LOCATION]
      ,[SUB_MENU_SEQ_ID]
      ,A.[STYLE_CSS]
      ,A.[PAGE_ACTION]
      ,[IS_PARENT]
,Case when A.STATUS_MASTER ='AC' THEN 'ACTIVE' ELSE 'INACTIVE' END [STATUS_MASTER] 
  FROM [vmaster].[TBL_SUB_MENU] A
  INNER JOIN vmaster.TBL_MAIN_MENU AS M ON  A.MAIN_MENU_ID=M.MAIN_MENU_ID
  WHERE A.STATUS_MASTER =@STATUS 
  AND  
  	CASE when @SUB_MENU_ID  <>'' and @SUB_MENU_ID <>'0' then
	charindex(',' +convert(varchar(max),a.SUB_MENU_ID  ) +',',','+@SUB_MENU_ID +',') else 1 end >0 



END
