CREATE PROCEDURE [VMaster].[SUBMIT_ANIMAL_HUNTING_CHARGES_MASTER_HDR]
(
    @ANIMAL_HUNT_CHARGE_ID INT,
    @Role varchar(50)='Administrator'
)

AS
BEGIN	
SET NOCOUNT ON
BEGIN TRY
BEGIN TRANSACTION
IF NOT EXISTS(SELECT 'X' FROM [VMaster].[TBL_ANIMAL_HUNTING_CHARGES_MASTER_HDR] WHERE ANIMAL_HUNT_CHARGE_ID = @ANIMAL_HUNT_CHARGE_ID)
BEGIN
    SELECT 'Error','Invalid Animal Hunting Charges ID. Record not found.. Contact Administrator','0'
END


ELSE IF EXISTS(SELECT 'X' FROM [VMaster].[TBL_ANIMAL_HUNTING_CHARGES_MASTER_HDR] WHERE ANIMAL_HUNT_CHARGE_ID = @ANIMAL_HUNT_CHARGE_ID AND STATUS_MASTER ='CL') 
AND @Role<>'Administrator'
BEGIN
    SELECT 'Error','Already Submitted.. Contact Administrator','0'
END


ELSE IF EXISTS(SELECT 'X' FROM [VMaster].[TBL_ANIMAL_HUNTING_CHARGES_MASTER_HDR] WHERE ANIMAL_HUNT_CHARGE_ID = @ANIMAL_HUNT_CHARGE_ID AND STATUS_MASTER ='CA')
BEGIN
    SELECT 'Error','Already Cancelled.. Contact Administrator','0'
END


ELSE BEGIN
    UPDATE [VMaster].[TBL_ANIMAL_HUNTING_CHARGES_MASTER_HDR]    SET STATUS_MASTER='CL'   WHERE ANIMAL_HUNT_CHARGE_ID=@ANIMAL_HUNT_CHARGE_ID
    SELECT '','Animal Hunting Charges Submitted Successfully','CL'
END

COMMIT TRANSACTION
END TRY
BEGIN CATCH
DECLARE @msg VARCHAR(MAX)=''
SET @msg = 'ERROR: ' + ERROR_MESSAGE() + ' at ' 
            + COALESCE(ERROR_PROCEDURE(), '')
            + COALESCE (' line:' + CONVERT(VARCHAR(30), ERROR_LINE()), '')

ROLLBACK TRAN
RAISERROR (@msg,0,1) WITH NOWAIT
END CATCH
END
GO
