   SET [AIRLINE_NAME] = @AIRLINE_NAME
      ,[REMARKS] = @REMARKS
      ,[STATUS_MASTER] = @STATUS_MASTER
      ,[MODIFIED_BY] = @USER
      ,[MODIFIED_DATE] = GETDATE()
      ,[MODIFIED_MAC_ADDRESS] = @MAC_ADDRESS

WHERE AIRLINE_ID=@AIRLINE_ID

SELECT '','RECORD UPDATED SUCCESSFULL',@AIRLINE_ID 

END
END

