CREATE   PROCEDURE [VMaster].[UPDATE_BUSINESS_PARTNER_MASTER]
(
    @BP_ID INT,
    @BP_TYPE VARCHAR(50),
    @BP_NAME VARCHAR(250),
    @BP_SHORT_CODE VARCHAR(50),
    @TIN_NUMBER VARCHAR(100),
    @VAT_NUMBER VARCHAR(50),
    @CONTACT_PERSON VARCHAR(50),
    @CONTACT_NUMBER VARCHAR(50),
    @ADDRESS VARCHAR(1500),
    @EMAIL_ADDRESS VARCHAR(100),
    @PHONE_NUMBER_2 VARCHAR(50),
    @COUNTRY_ID INT,
    @REGION_ID INT,
    @DISTRICT_ID INT,
    @LOCATION VARCHAR(100),
    @NATURE_OF_BUSINESS VARCHAR(50),
    @CREDIT_ALLOWED VARCHAR(50),
    @COMPANY_HEAD_CONTACT_PERSON VARCHAR(250),
    @COMPANY_HEAD_PHONE_NO VARCHAR(250),
    @COMPANY_HEAD_EMAIL VARCHAR(250),
    @ACCOUNTS_CONTACT_PERSON VARCHAR(250),
    @ACCOUNTS_PHONE_NO VARCHAR(250),
    @ACCOUNTS_EMAIL VARCHAR(250),
    @CURRENCY_ID INT,
    @PAYMENT_TERMS VARCHAR(2500),
    @REMARKS VARCHAR(2000),
    @STATUS_MASTER VARCHAR(20),
    @USER VARCHAR(50),
    @MAC_ADDRESS VARCHAR(50)
)
AS
BEGIN
    SET NOCOUNT ON

    IF NOT EXISTS
    (
        SELECT 'check'
        FROM [VMaster].[TBL_BUSINESS_PARTNER_MASTER]
        WHERE BP_ID=@BP_ID
    )
    BEGIN
        SELECT 'ERROR','RECORD DOES NOT EXIST',''
     
    END

    IF EXISTS
    (
        SELECT 1
        FROM [VMaster].[TBL_BUSINESS_PARTNER_MASTER]
        WHERE BP_NAME=@BP_NAME
          AND BP_ID<>@BP_ID
    )
    BEGIN
        SELECT 'ERROR','BUSINESS PARTNER ALREADY EXISTS',''
   
    END
	else begin

    UPDATE [VMaster].[TBL_BUSINESS_PARTNER_MASTER]
    SET
        BP_TYPE=@BP_TYPE,
        BP_NAME=@BP_NAME,
        BP_SHORT_CODE=@BP_SHORT_CODE,
        TIN_NUMBER=@TIN_NUMBER,
        VAT_NUMBER=@VAT_NUMBER,
        CONTACT_PERSON=@CONTACT_PERSON,
        CONTACT_NUMBER=@CONTACT_NUMBER,
        ADDRESS=@ADDRESS,
        EMAIL_ADDRESS=@EMAIL_ADDRESS,
        PHONE_NUMBER_2=@PHONE_NUMBER_2,
        COUNTRY_ID=@COUNTRY_ID,
        REGION_ID=@REGION_ID,
        DISTRICT_ID=@DISTRICT_ID,
        LOCATION=@LOCATION,
        NATURE_OF_BUSINESS=@NATURE_OF_BUSINESS,
        CREDIT_ALLOWED=@CREDIT_ALLOWED,
        COMPANY_HEAD_CONTACT_PERSON=@COMPANY_HEAD_CONTACT_PERSON,
        COMPANY_HEAD_PHONE_NO=@COMPANY_HEAD_PHONE_NO,
        COMPANY_HEAD_EMAIL=@COMPANY_HEAD_EMAIL,
        ACCOUNTS_CONTACT_PERSON=@ACCOUNTS_CONTACT_PERSON,
        ACCOUNTS_PHONE_NO=@ACCOUNTS_PHONE_NO,
        ACCOUNTS_EMAIL=@ACCOUNTS_EMAIL,
        CURRENCY_ID=@CURRENCY_ID,
        PAYMENT_TERMS=@PAYMENT_TERMS,
        REMARKS=@REMARKS,
        STATUS_MASTER=@STATUS_MASTER,
        MODIFIED_BY=@USER,
        MODIFIED_DATE=GETDATE(),
        MODIFIED_MAC_ADDRESS=@MAC_ADDRESS
    WHERE BP_ID=@BP_ID;

    SELECT '','RECORD UPDATED SUCCESSFULLY',@BP_ID
END
 end

