CREATE PROCEDURE [VMaster].[UPDATE_TRAILER_MASTER]
(
    @TRAILER_ID INT,
    @TRAILER_NO VARCHAR(50),
    @TRAILER_TYPE_ID INT,
    @TRAILER_CHASSIS_NO VARCHAR(100),
    @TRAILER_DESCRIPTION VARCHAR(100),
    @VEHICLE_CONTROL_NO VARCHAR(50),
    @TRAILER_OWNED_COMPANY_ID INT,
    @TITLE_HOLDER VARCHAR(50),
    @TITLE_HOLDER_TIN_NO VARCHAR(50),
    @TITLE_HOLDER_ADDRESS VARCHAR(50),
    @MAKE VARCHAR(50),
    @MODEL VARCHAR(50),
    @MODEL_NO VARCHAR(50),
    @BODY_TYPE VARCHAR(50),
    @CLASS VARCHAR(50),
    @MANUFACTURE_YEAR INT,
    @TARE_WEIGHT DECIMAL(15,2),
    @GROSS_WEIGHT DECIMAL(15,2),
    @IMPORTED_COUNTRY_ID INT,
    @IMPORTED_SUPPLIER_ID INT,
    @PURCHASE_DATE DATETIME,
    @LATEST_INSURANCE_NO VARCHAR(50),
    @INSURANCE_AMOUNT DECIMAL(15,2),
    @GOODS_CAPACITY VARCHAR(80),
    @REMARKS VARCHAR(1000),
    @STATUS_MASTER VARCHAR(20),
    @USER VARCHAR(50),
    @MAC_ADDRESS VARCHAR(50)
)
AS
BEGIN
    SET NOCOUNT ON;

    IF EXISTS
    (
        SELECT 1
        FROM VMaster.TBL_TRAILER_MASTER_HDR
        WHERE TRAILER_NO=@TRAILER_NO
        AND TRAILER_ID<>@TRAILER_ID
    )
    BEGIN
        SELECT 'ERROR','TRAILER NUMBER ALREADY EXISTS',''
 
    END
	ELSE BEGIN
    UPDATE VMaster.TBL_TRAILER_MASTER_HDR
    SET
        TRAILER_NO=@TRAILER_NO,
        TRAILER_TYPE_ID=@TRAILER_TYPE_ID,
        TRAILER_CHASSIS_NO=@TRAILER_CHASSIS_NO,
        TRAILER_DESCRIPTION=@TRAILER_DESCRIPTION,
        VEHICLE_CONTROL_NO=@VEHICLE_CONTROL_NO,
        TRAILER_OWNED_COMPANY_ID=@TRAILER_OWNED_COMPANY_ID,
        TITLE_HOLDER=@TITLE_HOLDER,
        TITLE_HOLDER_TIN_NO=@TITLE_HOLDER_TIN_NO,
        TITLE_HOLDER_ADDRESS=@TITLE_HOLDER_ADDRESS,
        MAKE=@MAKE,
        MODEL=@MODEL,
        MODEL_NO=@MODEL_NO,
        BODY_TYPE=@BODY_TYPE,
        CLASS=@CLASS,
        MANUFACTURE_YEAR=@MANUFACTURE_YEAR,
        TARE_WEIGHT=@TARE_WEIGHT,
        GROSS_WEIGHT=@GROSS_WEIGHT,
        IMPORTED_COUNTRY_ID=@IMPORTED_COUNTRY_ID,
        IMPORTED_SUPPLIER_ID=@IMPORTED_SUPPLIER_ID,
        PURCHASE_DATE=@PURCHASE_DATE,
        LATEST_INSURANCE_NO=@LATEST_INSURANCE_NO,
        INSURANCE_AMOUNT=@INSURANCE_AMOUNT,
        GOODS_CAPACITY=@GOODS_CAPACITY,
        REMARKS=@REMARKS,
        STATUS_MASTER=@STATUS_MASTER,
        MODIFIED_BY=@USER,
        MODIFIED_DATE=GETDATE(),
        MODIFIED_MAC_ADDRESS=@MAC_ADDRESS
    WHERE TRAILER_ID=@TRAILER_ID

    SELECT '','RECORD UPDATED SUCCESSFULLY',@TRAILER_ID
END
END
 

