CREATE PROCEDURE [VPayEntries].[DELETE_HOLIDAY_ENTRIES]
(
    @HOLIDAY_ID INT,
    @USER VARCHAR(50),
    @ROLE VARCHAR(50),
    @MAC_ADDRESS VARCHAR(50)
)
AS
BEGIN

SET NOCOUNT ON;

IF @ROLE <> 'Admin'
BEGIN
    SELECT 'error','No Rights To Delete',''
END

ELSE IF NOT EXISTS
(
    SELECT 'X'
    FROM [VPayEntries].[TBL_HOLIDAY_ENTRIES]
    WHERE HOLIDAY_ID=@HOLIDAY_ID
)
BEGIN
    SELECT 'error','RECORD NOT EXISTS',@HOLIDAY_ID
END

ELSE
BEGIN

DELETE FROM [VPayEntries].[TBL_HOLIDAY_ENTRIES]
WHERE HOLIDAY_ID=@HOLIDAY_ID


SELECT '',
       'Data Deleted Successfully',
       @HOLIDAY_ID

END

END
 

