)
AS
BEGIN

    SET NOCOUNT ON

        IF @ROLE <> 'Admin'
        BEGIN
            SELECT 
                'error' ,'No Rights To Delete', '' 
        END


        IF NOT EXISTS
        (
            SELECT 'check'
            FROM [VPayEntries].[NEW_EMPLOYEE_DATABASE]
            WHERE EMP_ID = @EMP_ID
        )
        BEGIN
            SELECT 
                'error','RECORD NOT EXISTS',  ''
        END
     ELSE  BEGIN  

        DELETE FROM [VPayEntries].[NEW_EMPLOYEE_DATABASE]
        WHERE EMP_ID = @EMP_ID
        SELECT 
            '' ,'Data Deleted Successfully' ,  @EMP_ID
 

END
end

