/****** Object:  StoredProcedure [VPayEntries].[SAVE_HOLIDAY_ENTRIES]    Script Date: 29 Jul 2026 18:22:13 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [VPayEntries].[SAVE_HOLIDAY_ENTRIES]
(
    @HOLIDAY_DATE DATETIME,
    @HOLIDAY_REASON VARCHAR(100),
    @REMARKS VARCHAR(1000),
    @STATUS_MASTER VARCHAR(20),
    @USER VARCHAR(50),
    @MAC_ADDRESS VARCHAR(50)
)
AS
BEGIN
SET NOCOUNT ON;

IF EXISTS
(
    SELECT 'X'
    FROM [VPayEntries].[TBL_HOLIDAY_ENTRIES]
    WHERE HOLIDAY_DATE=@HOLIDAY_DATE
)
BEGIN
    SELECT 'error','HOLIDAY ENTRY ALREADY EXISTS','0'
END

ELSE
BEGIN

INSERT INTO [VPayEntries].[TBL_HOLIDAY_ENTRIES]
(
    HOLIDAY_DATE,
    HOLIDAY_REASON,
    REMARKS,
    STATUS_MASTER,
    CREATED_BY,
    CREATED_DATE,
    CREATED_MAC_ADDRESS,
    MODIFIED_BY,
    MODIFIED_DATE,
    MODIFIED_MAC_ADDRESS
)
VALUES
(
    @HOLIDAY_DATE,
    @HOLIDAY_REASON,
    @REMARKS,
    @STATUS_MASTER,
    @USER,
    GETDATE(),
    @MAC_ADDRESS,
    @USER,
    GETDATE(),
    @MAC_ADDRESS
)

DECLARE @LAST_INSERTED_ID INT = SCOPE_IDENTITY();

SELECT '' AS STATUS,
       'Data Saved Successfully' AS MESSAGE,
       @LAST_INSERTED_ID AS DATA;

END
END
 

