/****** Object:  StoredProcedure [VPayEntries].[SHOW_HOLIDAY_ENTRIES]    Script Date: 29 Jul 2026 18:22:13 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [VPayEntries].[SHOW_HOLIDAY_ENTRIES]
(
    @STATUS VARCHAR(20)
)
AS
BEGIN

SET NOCOUNT ON;

SELECT
    HOLIDAY_ID,
    REPLACE(CONVERT(VARCHAR(50),HOLIDAY_DATE,106),' ','-') HOLIDAY_DATE,
    HOLIDAY_REASON,
    REMARKS,
    CASE 
        WHEN STATUS_MASTER='AC' THEN 'ACTIVE'
        ELSE 'INACTIVE'
    END STATUS_MASTER

FROM [VPayEntries].[TBL_HOLIDAY_ENTRIES]

WHERE STATUS_MASTER=@STATUS

END
 

GO
/****** Object:  StoredProcedure [VPayEntries].[SHOW_NEW_EMPLOYEE_DATABASE]    Script Date: 29 Jul 2026 18:22:13 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [VPayEntries].[SHOW_NEW_EMPLOYEE_DATABASE]
(
	@STATUS VARCHAR(50)
)

AS
BEGIN

SET NOCOUNT ON


SELECT 
	A.[SNO],
	A.[EMP_ID],
	A.[INT_TITLES],
	A.[FIRST_NAME],
	A.[MIDDLE_NAME],
	A.[LAST_NAME],
	REPLACE(CONVERT(VARCHAR(60),A.[DATE_OF_BIRTH],106),' ','-') AS DATE_OF_BIRTH,
	A.[AGE],
	A.[GENDER],
	REPLACE(CONVERT(VARCHAR(60),A.[DATE_OF_JOINING],106),' ','-') AS DATE_OF_JOINING,

	C.COMPANY_NAME,
	D.DEPARTMENT_NAME,
	DG.DESIGNATION_NAME,
	CA.CAMP_NAME,
	S.STORE_NAME,

	A.[BASIC_SALARY],
	A.[GROSS],
	A.[EMP_PH_NO],
	A.[EMP_MAILID],
	A.[APPROVED_BY],
	A.[REMARKS],

	CASE 
		WHEN A.STATUS_MASTER='AC' THEN 'ACTIVE'
		ELSE 'INACTIVE'
	END AS STATUS_MASTER


FROM [VPayEntries].[NEW_EMPLOYEE_DATABASE] AS A


LEFT JOIN VMASTER.TBL_COMPANY_MASTER AS C 
ON C.COMPANY_ID=A.COMPANY_ID


LEFT JOIN VMASTER.TBL_DEPARTMENT_MASTER AS D 
ON D.DEPARTMENT_ID=A.DEPARTMENT_ID


LEFT JOIN VMASTER.TBL_DESIGNATION_MASTER AS DG 
ON DG.DESIGNATION_ID=A.DESIGNATION_ID


LEFT JOIN VMASTER.TBL_CAMP_MASTER AS CA 
ON CA.CAMP_ID=A.CAMP_ID


LEFT JOIN VMASTER.TBL_STORE_MASTER AS S 
ON S.STORE_ID=A.STORE_ID


WHERE A.STATUS_MASTER=@STATUS


END
 

GO
