	@DATE_OF_BIRTH DATETIME,
	@AGE VARCHAR(50),
	@GENDER VARCHAR(20),
	@TRIAL_PERIOD_VALID_FROM DATETIME,
	@TRIAL_PERIOD_VALID_TO DATETIME,
	@DATE_OF_JOINING DATETIME,
	@RELAVANT_EXPERIENCE VARCHAR(50),
	@MARITAL_STATUS VARCHAR(50),
	@BLOOD_GROUP_ID INT,
	@EMPLOYEE_SKILL_STATUS VARCHAR(50),
	@COMPANY_ID INT,
	@DEPARTMENT_ID INT,
	@DESIGNATION_ID INT,
	@DEPARTMENT_GROUP_ID INT,
	@DESIGNATION_GROUP_ID INT,
	@CAMP_ID INT,
	@STORE_ID INT,
	@EMPLOYMENT_TYPE_ID INT,
	@SALARY_SCALE_ID INT,
	@BASIC_SALARY DECIMAL(15,2),
	@GROSS DECIMAL(15,2),
	@CURRENCY_ID INT,
	@COUNTRY_ID INT,
	@REGION_ID INT,
	@DISTRICT_ID INT,
	@LOCATION_ID INT,
	@ADDRESS_STREET VARCHAR(250),
	@PAYMENT_MODE_ID INT,
	@BANK_ID INT,
	@ACCOUNT_NO VARCHAR(50),
	@EMP_PH_NO VARCHAR(50),
	@EMP_MAILID VARCHAR(50),
	@APPROVED_BY VARCHAR(50),
	@REMARKS VARCHAR(1000),
	@STATUS_MASTER VARCHAR(20),
	@USER VARCHAR(50),
	@MAC_ADDRESS VARCHAR(50)
)

AS
BEGIN

SET NOCOUNT ON


IF EXISTS
(
	SELECT 'X'
	FROM [VPayEntries].[NEW_EMPLOYEE_DATABASE]
	WHERE EMP_ID=@EMP_ID
	AND SNO<>@SNO
)
BEGIN
	SELECT 'error','EMPLOYEE ALREADY EXISTS','0'
END

ELSE
BEGIN

UPDATE [VPayEntries].[NEW_EMPLOYEE_DATABASE]

SET
	EMP_ID=@EMP_ID,
	INT_TITLES=@INT_TITLES,
	FIRST_NAME=@FIRST_NAME,
	MIDDLE_NAME=@MIDDLE_NAME,
	LAST_NAME=@LAST_NAME,
	DATE_OF_BIRTH=@DATE_OF_BIRTH,
	AGE=@AGE,
	GENDER=@GENDER,
	TRIAL_PERIOD_VALID_FROM=@TRIAL_PERIOD_VALID_FROM,
	TRIAL_PERIOD_VALID_TO=@TRIAL_PERIOD_VALID_TO,
	DATE_OF_JOINING=@DATE_OF_JOINING,
	RELAVANT_EXPERIENCE=@RELAVANT_EXPERIENCE,
	MARITAL_STATUS=@MARITAL_STATUS,
	BLOOD_GROUP_ID=@BLOOD_GROUP_ID,
	EMPLOYEE_SKILL_STATUS=@EMPLOYEE_SKILL_STATUS,
	COMPANY_ID=@COMPANY_ID,
	DEPARTMENT_ID=@DEPARTMENT_ID,
	DESIGNATION_ID=@DESIGNATION_ID,
	DEPARTMENT_GROUP_ID=@DEPARTMENT_GROUP_ID,
	DESIGNATION_GROUP_ID=@DESIGNATION_GROUP_ID,
	CAMP_ID=@CAMP_ID,
	STORE_ID=@STORE_ID,
	EMPLOYMENT_TYPE_ID=@EMPLOYMENT_TYPE_ID,
	SALARY_SCALE_ID=@SALARY_SCALE_ID,
	BASIC_SALARY=@BASIC_SALARY,
	GROSS=@GROSS,
	CURRENCY_ID=@CURRENCY_ID,
	COUNTRY_ID=@COUNTRY_ID,
	REGION_ID=@REGION_ID,
	DISTRICT_ID=@DISTRICT_ID,
	LOCATION_ID=@LOCATION_ID,
	ADDRESS_STREET=@ADDRESS_STREET,
	PAYMENT_MODE_ID=@PAYMENT_MODE_ID,
	BANK_ID=@BANK_ID,
	ACCOUNT_NO=@ACCOUNT_NO,
	EMP_PH_NO=@EMP_PH_NO,
	EMP_MAILID=@EMP_MAILID,
	APPROVED_BY=@APPROVED_BY,
	REMARKS=@REMARKS,
	STATUS_MASTER=@STATUS_MASTER,
	MODIFIED_BY=@USER,
	MODIFIED_DATE=GETDATE(),
	MODIFIED_MAC_ADDRESS=@MAC_ADDRESS

WHERE SNO=@SNO


SELECT '','RECORD UPDATED SUCCESSFULL',@SNO


END

END
 

GO
